import{_ as o,o as a,c as r,a0 as s}from"./chunks/framework.DCluYYrN.js";const c=JSON.parse('{"title":"Perguntas frequentes","description":"","frontmatter":{},"headers":[],"relativePath":"pt_BR/guide/faq.md","filePath":"pt_BR/guide/faq.md"}'),i={name:"pt_BR/guide/faq.md"};function t(n,e,u,d,l,m){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="perguntas-frequentes" tabindex="-1">Perguntas frequentes <a class="header-anchor" href="#perguntas-frequentes" aria-label="Permalink to &quot;Perguntas frequentes&quot;">​</a></h1><h2 id="kernelsu-oferece-suporte-ao-meu-dispositivo" tabindex="-1">KernelSU oferece suporte ao meu dispositivo? <a class="header-anchor" href="#kernelsu-oferece-suporte-ao-meu-dispositivo" aria-label="Permalink to &quot;KernelSU oferece suporte ao meu dispositivo?&quot;">​</a></h2><p>O KernelSU suporta dispositivos rodando Android com bootloader desbloqueado. No entanto, o suporte oficial é apenas para kernels Linux GKI 5.10+ (na prática isso significa que seu dispositivo precisa ter Android 12 de fábrica para ser compatível).</p><p>Você pode verificar facilmente o suporte para o seu dispositivo através do gerenciador do KernelSU, que está disponível <a href="https://github.com/tiann/KernelSU/releases" target="_blank" rel="noreferrer">aqui</a>.</p><p>Se o app mostrar <code>Não instalado</code>, significa que seu dispositivo é oficialmente suportado pelo KernelSU.</p><p>Se o app mostrar <code>Sem suporte</code>, significa que seu dispositivo não é oficialmente suportado no momento. No entanto, você pode compilar o código-fonte do kernel e integrar o KernelSU para fazê-lo funcionar, ou usar <a href="./unofficially-support-devices.html">Dispositivos com suporte não oficial</a>.</p><h2 id="para-usar-o-kernelsu-precisa-desbloquear-o-bootloader" tabindex="-1">Para usar o KernelSU precisa desbloquear o bootloader? <a class="header-anchor" href="#para-usar-o-kernelsu-precisa-desbloquear-o-bootloader" aria-label="Permalink to &quot;Para usar o KernelSU precisa desbloquear o bootloader?&quot;">​</a></h2><p>Certamente, sim.</p><h2 id="kernelsu-suporta-modulos" tabindex="-1">KernelSU suporta módulos? <a class="header-anchor" href="#kernelsu-suporta-modulos" aria-label="Permalink to &quot;KernelSU suporta módulos?&quot;">​</a></h2><p>Sim, a maioria dos módulos Magisk funcionam no KernelSU. No entanto, se seu módulo precisar modificar arquivos <code>/system</code>, você precisa instalar um <a href="./metamodule.html">metamodule</a> (como <code>meta-overlayfs</code>). Outros recursos de módulos funcionam sem um metamodule. Confira o <a href="./module.html">Guia de módulos</a> para mais informações.</p><h2 id="kernelsu-suporta-xposed" tabindex="-1">KernelSU suporta Xposed? <a class="header-anchor" href="#kernelsu-suporta-xposed" aria-label="Permalink to &quot;KernelSU suporta Xposed?&quot;">​</a></h2><p>Sim, você pode usar LSPosed (ou outro derivado moderno do Xposed) com <a href="https://github.com/Dr-TSNG/ZygiskNext" target="_blank" rel="noreferrer">ZygiskNext</a>.</p><h2 id="kernelsu-suporta-zygisk" tabindex="-1">KernelSU suporta Zygisk? <a class="header-anchor" href="#kernelsu-suporta-zygisk" aria-label="Permalink to &quot;KernelSU suporta Zygisk?&quot;">​</a></h2><p>KernelSU não tem suporte integrado ao Zygisk, mas você pode usar um módulo como <a href="https://github.com/Dr-TSNG/ZygiskNext" target="_blank" rel="noreferrer">ZygiskNext</a> para suportá-lo.</p><h2 id="por-que-meus-modulos-nao-funcionam-apos-uma-instalacao-nova" tabindex="-1">Por que meus módulos não funcionam após uma instalação nova? <a class="header-anchor" href="#por-que-meus-modulos-nao-funcionam-apos-uma-instalacao-nova" aria-label="Permalink to &quot;Por que meus módulos não funcionam após uma instalação nova?&quot;">​</a></h2><p>Se seus módulos precisam modificar arquivos <code>/system</code>, você precisa instalar um <a href="./metamodule.html">metamodule</a> para montar o diretório <code>system</code>. Outros recursos de módulos (scripts, sepolicy, system.prop) funcionam sem um metamodule.</p><p><strong>Solução</strong>: Consulte o <a href="./metamodule.html">Guia de Metamodule</a> para instruções de instalação.</p><h2 id="o-que-e-um-metamodule-e-por-que-preciso-dele" tabindex="-1">O que é um metamodule e por que preciso dele? <a class="header-anchor" href="#o-que-e-um-metamodule-e-por-que-preciso-dele" aria-label="Permalink to &quot;O que é um metamodule e por que preciso dele?&quot;">​</a></h2><p>Um metamodule é um módulo especial que fornece infraestrutura para montar módulos regulares. Consulte o <a href="./metamodule.html">Guia de Metamodule</a> para uma explicação completa.</p><h2 id="kernelsu-e-compativel-com-o-magisk" tabindex="-1">KernelSU é compatível com o Magisk? <a class="header-anchor" href="#kernelsu-e-compativel-com-o-magisk" aria-label="Permalink to &quot;KernelSU é compatível com o Magisk?&quot;">​</a></h2><p>O sistema de módulos do KernelSU está em conflito com a montagem mágica do Magisk. Se houver algum módulo ativado no KernelSU, todo o Magisk deixará de funcionar.</p><p>No entanto, se você usar apenas o <code>su</code> do KernelSU, ele funcionará bem com o Magisk. O KernelSU modifica o <code>kernel</code>, enquanto o Magisk modifica o <code>ramdisk</code>, permitindo que ambos trabalhem juntos.</p><h2 id="kernelsu-substituira-o-magisk" tabindex="-1">KernelSU substituirá o Magisk? <a class="header-anchor" href="#kernelsu-substituira-o-magisk" aria-label="Permalink to &quot;KernelSU substituirá o Magisk?&quot;">​</a></h2><p>Acreditamos que não, e esse não é o nosso objetivo. O Magisk é bom o suficiente para solução root do espaço do usuário e terá uma longa vida. O objetivo do KernelSU é fornecer uma interface de kernel aos usuários, não substituindo o Magisk.</p><h2 id="kernelsu-oferece-suporte-a-dispositivos-nao-gki" tabindex="-1">KernelSU oferece suporte a dispositivos não-GKI? <a class="header-anchor" href="#kernelsu-oferece-suporte-a-dispositivos-nao-gki" aria-label="Permalink to &quot;KernelSU oferece suporte a dispositivos não-GKI?&quot;">​</a></h2><p>É possível. Mas você deve baixar o código-fonte do kernel e integrar o KernelSU à árvore do código-fonte e compilar o kernel você mesmo.</p><h2 id="kernelsu-oferece-suporte-a-dispositivos-abaixo-do-android-12" tabindex="-1">KernelSU oferece suporte a dispositivos abaixo do Android 12? <a class="header-anchor" href="#kernelsu-oferece-suporte-a-dispositivos-abaixo-do-android-12" aria-label="Permalink to &quot;KernelSU oferece suporte a dispositivos abaixo do Android 12?&quot;">​</a></h2><p>É o kernel do dispositivo que afeta a compatibilidade do KernelSU e não tem nada a ver com a versão do Android. A única restrição é que os dispositivos lançados com Android 12 devem ser kernel 5.10+ (dispositivos GKI). Então:</p><ol><li>Os dispositivos lançados com Android 12 devem ser compatíveis.</li><li>Dispositivos com kernel antigo (alguns dispositivos com Android 12 também têm o kernel antigo) são compatíveis (você mesmo deve compilar o kernel).</li></ol><h2 id="kernelsu-suporta-kernel-antigo" tabindex="-1">KernelSU suporta kernel antigo? <a class="header-anchor" href="#kernelsu-suporta-kernel-antigo" aria-label="Permalink to &quot;KernelSU suporta kernel antigo?&quot;">​</a></h2><p>É possível, o KernelSU é portado para o kernel 4.14 agora. Para kernels mais antigo, você precisa portar manualmente e PRs são sempre bem-vindas!</p><h2 id="como-integrar-o-kernelsu-para-um-kernel-antigo" tabindex="-1">Como integrar o KernelSU para um kernel antigo? <a class="header-anchor" href="#como-integrar-o-kernelsu-para-um-kernel-antigo" aria-label="Permalink to &quot;Como integrar o KernelSU para um kernel antigo?&quot;">​</a></h2><p>Por favor, verifique o guia <a href="./how-to-integrate-for-non-gki.html">Integração para dispositivos não-GKI</a>.</p><h2 id="por-que-a-minha-versao-do-android-e-13-e-o-kernel-mostra-android12-5-10" tabindex="-1">Por que a minha versão do Android é 13 e o kernel mostra &quot;android12-5.10&quot;? <a class="header-anchor" href="#por-que-a-minha-versao-do-android-e-13-e-o-kernel-mostra-android12-5-10" aria-label="Permalink to &quot;Por que a minha versão do Android é 13 e o kernel mostra &quot;android12-5.10&quot;?&quot;">​</a></h2><p>A versão do Kernel não tem nada a ver com a versão do Android. Se você precisar fazer o flash do kernel, use sempre a versão do kernel, a versão do Android não é tão importante.</p><h2 id="eu-sou-gki-1-0-posso-usar-isso" tabindex="-1">Eu sou GKI 1.0, posso usar isso? <a class="header-anchor" href="#eu-sou-gki-1-0-posso-usar-isso" aria-label="Permalink to &quot;Eu sou GKI 1.0, posso usar isso?&quot;">​</a></h2><p>GKI 1.0 é completamente diferente do GKI 2.0, você deve compilar o kernel sozinho.</p><h2 id="como-posso-fazer-system-rw" tabindex="-1">Como posso fazer <code>/system</code> RW? <a class="header-anchor" href="#como-posso-fazer-system-rw" aria-label="Permalink to &quot;Como posso fazer `/system` RW?&quot;">​</a></h2><p>Não recomendamos que você modifique a partição do sistema diretamente. Por favor, verifique <a href="./module.html">Guias de módulo</a> para modificá-lo sem sistema. Se você insiste em fazer isso, verifique <a href="https://github.com/HuskyDG/magic_overlayfs" target="_blank" rel="noreferrer">magisk_overlayfs</a>.</p><h2 id="kernelsu-pode-modificar-hosts-como-posso-usar-adaway" tabindex="-1">KernelSU pode modificar hosts? Como posso usar AdAway? <a class="header-anchor" href="#kernelsu-pode-modificar-hosts-como-posso-usar-adaway" aria-label="Permalink to &quot;KernelSU pode modificar hosts? Como posso usar AdAway?&quot;">​</a></h2><p>Claro. Mas o KernelSU não tem suporte a hosts integrados, você pode instalar um módulo como <a href="https://github.com/symbuzzer/systemless-hosts-KernelSU-module" target="_blank" rel="noreferrer">systemless-hosts</a> para fazer isso.</p>',41)])])}const h=o(i,[["render",t]]);export{c as __pageData,h as default};
